def find_zero(xs: list):
    x0 = 0.0  # Initial guess
    tolerance = 1e-7
    max_iterations = 1000
    for _ in range(max_iterations):
        y = poly(xs, x0)
        y_prime = poly_derivative(xs, x0)
        if abs(y_prime) < tolerance:
            raise ValueError('Derivative too small for Newton-Raphson method')
        x1 = x0 - y / y_prime
        if abs(x1 - x0) < tolerance:
            return x1
        x0 = x1
    raise ValueError('Exceeded maximum iterations without finding root')

